//! Regenerate scalar pole kernels from oneloopmaster's public exact expressions.
//! Run from the MadGraph checkout through the standalone maintenance workspace:
//! cargo run --release --manifest-path vendor/tirust/pole-kernels/maintenance/Cargo.toml --bin generate-poles -- vendor/tirust/pole-kernels/src
use oneloop::rust_codegen::{EmitOptions, RustEmitter};
use oneloop::{A0, B0, C0, D0, OneLoopExpressions, ScalarIntegral};
use std::path::PathBuf;
use symbolica::atom::Atom;

const SOURCE_REVISION: &str = "bd703d09a78f7849a6b86a07096e6f222fc01193";
const LAURENT_TAGS: [i32; 2] = [-1, -2];

fn generate(directory: PathBuf) -> Result<(), String> {
    let expressions = OneLoopExpressions::new();
    let mut emitter = RustEmitter::default();
    let mut files = Vec::new();
    let mut manifest =
        format!("oneloopmaster_revision={SOURCE_REVISION}\nlaurent_tags=-1,-2\nfinite_roots=0\n");
    for (family, symbol, file) in [
        (ScalarIntegral::A0, A0(), "generated_a0.rs"),
        (ScalarIntegral::B0, B0(), "generated_b0.rs"),
        (ScalarIntegral::C0, C0(), "generated_c0.rs"),
        (ScalarIntegral::D0, D0(), "generated_d0.rs"),
    ] {
        let parameters = (0..family.arity())
            .map(|index| {
                symbolica::symbol!(format!("madloop_pole_codegen_{}_{index}", family.name()))
                    .to_atom()
            })
            .collect::<Vec<_>>();
        // Excluding tag zero before evaluator construction removes the finite
        // expression roots, their helpers, and their arithmetic from the DAG.
        let roots = LAURENT_TAGS.map(|tag| {
            let mut arguments = vec![Atom::num(tag)];
            arguments.extend(parameters.iter().cloned());
            symbol.call(&arguments)
        });
        let module = emitter.emit(
            expressions
                .evaluator(&roots, &parameters)
                .map_err(|error| error.to_string())?,
            EmitOptions {
                inline_arithmetic: matches!(family, ScalarIntegral::A0 | ScalarIntegral::B0),
            },
        )?;
        if module.input_count != family.arity() || module.output_count != LAURENT_TAGS.len() {
            return Err(format!(
                "{} generator changed input/output shape",
                family.name()
            ));
        }
        // No scalar pole formula needs a dilogarithm. Reject an unexpected
        // dependency instead of quietly carrying finite-only work along.
        if module.source.contains("polylog2(") {
            return Err(format!(
                "{} pole graph unexpectedly contains a dilogarithm",
                family.name()
            ));
        }
        let source = module.source.replacen(
            "// Generated by examples/generate_native.rs from repaired exact expressions.",
            "// Generated by examples/generate_poles.rs from oneloopmaster Laurent roots [-1, -2].",
            1,
        );
        let statistics = format!(
            "{}: inputs={} outputs={} root_instructions={} helpers={} branches={} bytes={}\n",
            family.name(),
            module.input_count,
            module.output_count,
            module.instruction_count,
            module.helper_count,
            module.outlined_branch_count,
            source.len()
        );
        eprint!("{statistics}");
        manifest.push_str(&statistics);
        files.push((file, source));
    }
    let constants = emitter.constants_source().replacen(
        "// Generated by examples/generate_native.rs from repaired exact expressions.",
        "// Generated by examples/generate_poles.rs from oneloopmaster Laurent roots [-1, -2].",
        1,
    );
    if constants.contains("ConstantSpec::Polylog2") {
        return Err("pole constants unexpectedly require a dilogarithm".into());
    }
    files.push(("generated_constants.rs", constants));
    files.push(("generated_manifest.txt", manifest));
    // Finish every graph before writing any output, so an unsupported graph
    // cannot leave a partially regenerated kernel set.
    std::fs::create_dir_all(&directory).map_err(|error| error.to_string())?;
    for (file, source) in files {
        std::fs::write(directory.join(file), source).map_err(|error| error.to_string())?;
    }
    Ok(())
}

fn main() {
    let mut arguments = std::env::args().skip(1);
    let directory = PathBuf::from(
        arguments
            .next()
            .expect("usage: generate_poles OUTPUT_DIRECTORY"),
    );
    assert!(
        arguments.next().is_none(),
        "usage: generate_poles OUTPUT_DIRECTORY"
    );
    std::thread::Builder::new()
        .stack_size(128 * 1024 * 1024)
        .spawn(move || generate(directory))
        .expect("create generator thread")
        .join()
        .expect("pole generator panicked")
        .expect("generate exact scalar pole kernels");
}
